const section = (out, tag) => {
  const i = out.indexOf('###' + tag)
  if (i < 0) return null
  const rest = out.slice(i + tag.length + 3)
  const j = rest.indexOf('###')
  return (j < 0 ? rest : rest.slice(0, j)).trim()
}
const tryJSON = s => { try { return JSON.parse(s) } catch (e) { return null } }

